export const inlineScript = "\n  (function() {\n    const benchToggle = document.getElementById('bench-toggle');\n    const benchDrawer = document.getElementById('bench-drawer');\n    const benchChevron = document.getElementById('bench-chevron');\n    const confirmBtn = document.getElementById('confirm-roster-btn');\n\n    if (benchToggle && benchDrawer && benchChevron) {\n      benchToggle.addEventListener('click', () => {\n        const isHidden = benchDrawer.classList.contains('hidden');\n        if (isHidden) {\n          benchDrawer.classList.remove('hidden');\n          benchDrawer.classList.add('flex');\n          benchChevron.classList.add('rotate-180');\n        } else {\n          benchDrawer.classList.add('hidden');\n          benchDrawer.classList.remove('flex');\n          benchChevron.classList.remove('rotate-180');\n        }\n      });\n    }\n\n    if (confirmBtn) {\n      confirmBtn.addEventListener('click', () => {\n        const originalHtml = confirmBtn.innerHTML;\n        confirmBtn.innerHTML = '<span class=\"material-symbols-outlined animate-spin text-[20px]\">sync</span><span>Locking Starters...</span>';\n        confirmBtn.disabled = true;\n        setTimeout(() => {\n          confirmBtn.innerHTML = '<span class=\"material-symbols-outlined text-[20px]\">task_alt</span><span>Lineup Confirmed</span>';\n          confirmBtn.classList.remove('bg-primary-container');\n          confirmBtn.classList.add('bg-surface-bright', 'text-primary');\n        }, 800);\n      });\n    }\n  })();\n";
